module.exports = function(RED) {
    "use strict";
    const util = require("util");

    function parsePositiveInteger(value, fallback) {
        const parsed = parseInt(value, 10);
        if (!Number.isFinite(parsed) || parsed < 0) {
            return fallback;
        }
        return parsed;
    }

    function toDisplayText(value) {
        if (Buffer.isBuffer(value)) {
            return value.toString("utf8");
        }
        if (value === undefined) {
            return "";
        }
        if (value === null) {
            return "null";
        }
        if (typeof value === "string") {
            return value;
        }
        if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
            return value.toString();
        }
        try {
            return JSON.stringify(value, null, 2);
        } catch (err) {
            return util.inspect(value, { depth: 5, breakLength: 120 });
        }
    }

    function getDisplayValue(msg, property) {
        const normalized = (property || "payload").trim();
        if (!normalized || normalized === "msg" || normalized === "true") {
            return msg;
        }
        if (normalized.startsWith("msg.")) {
            return RED.util.getMessageProperty(msg, normalized.substring(4));
        }
        return RED.util.getMessageProperty(msg, normalized);
    }

    function CanvasTextNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        node.name = config.name;
        node.property = config.property || "payload";
        node.placeholder = config.placeholder || "";
        node.maxLength = parsePositiveInteger(config.maxLength, 12000);

        function publish(text, truncated, originalLength) {
            RED.comms.publish("canvas-text/" + node.id, {
                text: text,
                truncated: truncated,
                length: originalLength,
                property: node.property,
                updatedAt: Date.now()
            }, true);
        }

        node.on("input", function(msg, send, done) {
            try {
                const value = getDisplayValue(msg, node.property);
                let text = toDisplayText(value);
                const originalLength = text.length;
                let truncated = false;
                if (node.maxLength > 0 && text.length > node.maxLength) {
                    text = text.substring(0, node.maxLength) + "\n...";
                    truncated = true;
                }
                publish(text, truncated, originalLength);
                node.status({
                    fill: "green",
                    shape: "dot",
                    text: originalLength + " chars" + (truncated ? " truncated" : "")
                });
                if (done) {
                    done();
                }
            } catch (err) {
                node.status({ fill: "red", shape: "ring", text: err.message });
                if (done) {
                    done(err);
                } else {
                    node.error(err, msg);
                }
            }
        });

        node.on("close", function(removed, done) {
            RED.comms.publish("canvas-text/" + node.id, {}, false);
            node.status({});
            if (done) {
                done();
            }
        });
    }
    RED.nodes.registerType("canvas-text", CanvasTextNode);
};
